import{_ as i,C as e,o as l,c as n,E as r,a2 as o}from"./chunks/framework.mq20U3A6.js";const f=JSON.parse('{"title":"接收完成事件，不等于验收完成证据：状态服务的九个探针","description":"","frontmatter":{"title":"接收完成事件，不等于验收完成证据：状态服务的九个探针","date":"2026-10-21","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"状态服务接收完成事件，能否代表证据、身份与执行约束均已核验？","summary":"固定示例中的完成事件可在治理仍阻止时被接收；有效拒绝对照也存在。九个本地请求说明报告、身份授权与业务执行需要分开核验。","sources":"ASP v0.1 pinned example; A2-Failures v1; RCM v1; internal experiments","pageClass":"runtime-v6-article","item_id":"SIG-20261021-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-21-sig-20261021-003-2026-10-21-completion-evidence.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-10-21-completion-evidence.md","filePath":"zh/engineering/2026-10-21-completion-evidence.md","lastUpdated":null}'),s={name:"zh/engineering/2026-10-21-completion-evidence.md"};function h(p,t,c,g,m,b){const a=e("ArticleCover"),d=e("ArticleTableScroll");return l(),n("div",null,[r(a,{image:"/assets/covers/daily-2026-10-21-sig-20261021-003-2026-10-21-completion-evidence.png",kicker:"研究成果",title:"接收完成事件，不等于验收完成证据：状态服务的九个探针",summary:"固定示例中的完成事件可在治理仍阻止时被接收；有效拒绝对照也存在。九个本地请求说明报告、身份授权与业务执行需要分开核验。",version:"2026-10-21",languageHref:"/en/engineering/2026-10-21-completion-evidence",languageLabel:"English"}),r(d,{language:"zh"}),t[0]||(t[0]=o('<h1 id="接收完成事件-不等于验收完成证据-状态服务的九个探针" tabindex="-1">接收完成事件，不等于验收完成证据：状态服务的九个探针 <a class="header-anchor" href="#接收完成事件-不等于验收完成证据-状态服务的九个探针" aria-label="Permalink to &quot;接收完成事件，不等于验收完成证据：状态服务的九个探针&quot;">​</a></h1><p>一个任务可以被记录为“已完成”，同时仍处于“被阻止”的治理状态。在本次检查的状态服务示例中，这两件事确实同时发生。它提醒接入代理的平台工程师：接收事件、核验完成证据和允许实际动作，需要各自明确的责任主体。下面的请求表可用来检查这些环节是否被误当成同一层保证。</p><h2 id="一个固定示例的九次请求" tabindex="-1">一个固定示例的九次请求 <a class="header-anchor" href="#一个固定示例的九次请求" aria-label="Permalink to &quot;一个固定示例的九次请求&quot;">​</a></h2><p>ASP（智能体状态协议）分别描述存活、进度、独立观察和治理信息。本次内部实验不是重写一个简化服务，而是导入已捕获且未修改的作者示例，在本机回环地址启动其事件处理路径。固定提交为 <code>faf07a43b885204900f0049d010ab0e73e430de7</code>（本次源码版本标识）；运行环境为 Windows（微软桌面操作系统）与 Python（编程语言）3.13.13。配置的是合成的共享访问令牌，没有连接业务执行器。<a href="https://github.com/AgentStatusProtocol/spec/blob/faf07a43b885204900f0049d010ab0e73e430de7/implementations/python-status-server/server.py" target="_blank" rel="noreferrer">固定源码</a></p><p>表中每一行都来自本研究中心 2026-10-21 的内部 HTTP（超文本传输协议）请求记录，按执行顺序排列。202 表示本次事件接收响应，401 表示认证拒绝，409 表示该状态或优先级条件下的冲突拒绝；它们都不是外部业务动作的测量值。</p><table tabindex="0"><thead><tr><th>请求</th><th style="text-align:right;">响应码</th><th>请求后的任务状态</th><th>请求后的治理状态</th></tr></thead><tbody><tr><td>错误令牌尝试注册</td><td style="text-align:right;">401</td><td>无记录</td><td>无记录</td></tr><tr><td>注册前上报任务完成</td><td style="text-align:right;">409</td><td>无记录</td><td>无记录</td></tr><tr><td>使用共享令牌注册</td><td style="text-align:right;">202</td><td>无任务</td><td>正常</td></tr><tr><td>上报任务工作中</td><td style="text-align:right;">202</td><td>工作中</td><td>正常</td></tr><tr><td>以防护来源设置阻止</td><td style="text-align:right;">202</td><td>工作中</td><td>阻止，由防护来源设置</td></tr><tr><td>以自身来源尝试解除阻止</td><td style="text-align:right;">409</td><td>工作中</td><td>仍阻止</td></tr><tr><td>未附业务证据而上报完成</td><td style="text-align:right;">202</td><td>已完成</td><td>仍阻止</td></tr><tr><td>尝试把终态重新打开</td><td style="text-align:right;">409</td><td>仍已完成</td><td>仍阻止</td></tr><tr><td>同一共享令牌声明操作员来源并解除阻止</td><td style="text-align:right;">202</td><td>已完成</td><td>正常，由操作员来源设置</td></tr></tbody></table><p>错误令牌、未注册事件、低优先级解除和终态重开都被拒绝。这些对照很重要：不能把示例概括为“什么都接收”。真正需要解释的是，为什么四项拒绝成立时，缺乏业务完成证据的事件依然能进入终态。</p><h2 id="两个状态维度可以同时成立" tabindex="-1">两个状态维度可以同时成立 <a class="header-anchor" href="#两个状态维度可以同时成立" aria-label="Permalink to &quot;两个状态维度可以同时成立&quot;">​</a></h2><p>源码中的任务状态归约与治理状态归约分开处理。治理阻止没有在本次事件路径中变成“禁止接收完成报告”的条件；完成事件也不要求提交可核验的业务产物。因此，表中“已完成、仍阻止”首先是报告层允许表达的一组状态，不能改写成“外部业务已经绕过阻止执行”。本实验没有外部执行器，观察不到后一个结果。</p><p>来源优先级同样需要和调用者权限分开。自身来源不能解除防护来源设置的阻止，说明优先级规则在该用例有效。但同一共享凭据能把请求中的来源改称操作员，并被允许解除阻止，说明示例没有把每个调用者可声明的来源角色绑定到独立身份授权。一个被服务接受的角色标签，尚不足以成为可信的权限依据。</p><p>这不是作者未披露的生产安全承诺落空。配套说明明确排除了逐代理凭据范围控制，也没有声称示例已具备生产就绪或符合性验证。外部网关可能补上角色限制，执行器也可能在动作前另查阻止状态；本次都没有检查。结论限于这份固定示例的报告与执行边界。<a href="https://github.com/AgentStatusProtocol/spec/tree/faf07a43b885204900f0049d010ab0e73e430de7/implementations/python-status-server" target="_blank" rel="noreferrer">示例源码及配套说明</a></p><h2 id="报告、诊断与责任解除" tabindex="-1">报告、诊断与责任解除 <a class="header-anchor" href="#报告、诊断与责任解除" aria-label="Permalink to &quot;报告、诊断与责任解除&quot;">​</a></h2><p>A2-Failures（跨主体智能体失败研究）的公开第一版提供了作者报告的核验失败例子：有的发布路径要求失败后更换产物校验码并接受新挑战；另一个例子中，安全阻止没有约束另一代理提交发运记录。它们有助于区分“看见问题”和“问题约束后续行为”，但不是本次状态服务的部署轨迹，也不能用来给本实验附加失败频率。<a href="https://arxiv.org/html/2610.19342v1" target="_blank" rel="noreferrer">论文附录中的核验与行为案例</a></p><p>RCM（责任承诺模型）的第一版则定义了不同问题：解除责任前，委托方需要检查与约定绑定的完成证据；约定修订需要重新同意，旧版本不能冒充当前版本。证据不足也不自动等于违反承诺。<a href="https://arxiv.org/html/2610.21243v1" target="_blank" rel="noreferrer">责任生命周期说明</a></p><p>同日的内部规格派生模型枚举了 16 种布尔条件组合；人为设定的“仅看完成状态”规则比带约束规则多接纳七种组合。这个结果只是把不同条件的信息差异显式化：模型把证据判定视作已有答案，最困难的证据可信性问题并未解决。它没有运行作者的责任模型实现，不能验证其性能、安全性或优越性。</p><p>我们的比较判断是：状态协议提供报告与观察语义，失败研究提供诊断材料，责任模型描述解除义务的条件。三者不是同一任务、同一部署或同一安全评测；这里也不建立一个“谁更安全”的排名。</p><h2 id="把检查放到有权裁决的环节" tabindex="-1">把检查放到有权裁决的环节 <a class="header-anchor" href="#把检查放到有权裁决的环节" aria-label="Permalink to &quot;把检查放到有权裁决的环节&quot;">​</a></h2><p>对接入状态服务的系统，下面是从观察形成的职责建议，不是本次已实现或已测试的补丁。贯穿例子仍是“某代理提交完成事件”。</p><table tabindex="0"><thead><tr><th>环节与责任主体</th><th>接收什么</th><th>应产出什么</th><th>失败或不确定时怎样处理</th></tr></thead><tbody><tr><td>身份网关</td><td>已认证调用者及其声明角色</td><td>该调用者可声明的身份与来源范围</td><td>无权声明的角色应拒绝</td></tr><tr><td>状态接收服务</td><td>授权范围内的事件</td><td>可追溯的状态记录</td><td>冲突拒绝；无足够事实时保留不确定</td></tr><tr><td>完成验证者</td><td>当前约定、产物版本及完成证据</td><td>对具体产物的验收决定</td><td>缺少前置产物则等待；证据不足交回核验，不能自动宣布完成</td></tr><tr><td>业务执行器</td><td>有效验收决定与当前限制</td><td>被允许的业务动作</td><td>明确限制应拒绝动作；授权归属不明时先对账</td></tr></tbody></table><p>角色名优先级不能替代第一行；状态接收响应不能替代第三行；第三行的验收也不能凭空保证第四行已执行限制。对已经另外部署了这些检查的系统，本文不是宣称它仍可被绕过。要得到这种判断，必须检查实际接入路径和拒绝用例。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>“内部实验”指本研究中心在单机回环地址测得的响应和状态，不是独立第三方验证。“公开一手材料”包括作者规范和代码，能定位其定义与实现，却不自动成为独立验证。“作者报告”指论文给出的诊断案例；本文未复算其频率。“职责建议”是我们从这些边界作出的工程解释。</p><ul><li><a href="https://arxiv.org/html/2610.21538v1" target="_blank" rel="noreferrer">状态协议第一版</a>：工作提案，状态、观察、治理优先级与部署边界的来源；不是业务执行已被约束的测试证据。</li><li><a href="https://github.com/AgentStatusProtocol/spec/blob/faf07a43b885204900f0049d010ab0e73e430de7/implementations/python-status-server/server.py" target="_blank" rel="noreferrer">固定示例源码</a>：作者实现，固定提交如上；本次实际执行其事件处理路径。</li><li><a href="https://arxiv.org/html/2610.19342v1" target="_blank" rel="noreferrer">跨主体失败研究第一版</a>：2026 年研究预印本，核验案例与诊断边界的来源。受限原始运行及完整评估包未取得；自动标注可能漏判或错判。</li><li><a href="https://arxiv.org/html/2610.21243v1" target="_blank" rel="noreferrer">责任承诺模型第一版</a>：2026 年研究预印本，责任解除的规格比较材料。没有作为本次可执行实现或安全证明使用。</li><li>本研究中心 2026-10-21 内部实验记录：九个实际请求与逐次状态快照；另有 16 条规格派生模型条件。两者证据形态不同，数量不能相加当成同一系统的测试覆盖。</li></ul><p>所有外部资料均来自本次获准的同日研究对象及其已读材料。引用预印本或代码只确定来源与版本，不代表认可论文全部结论，也不把作者实验升级为独立验证。</p><h2 id="这些探针没有检验什么" tabindex="-1">这些探针没有检验什么 <a class="header-anchor" href="#这些探针没有检验什么" aria-label="Permalink to &quot;这些探针没有检验什么&quot;">​</a></h2><p>本实验只覆盖一个示例提交的事件接收路径，没有启动存活检测线程或观察界面，没有测试并发、重启、持续事件流、网络分区或外部动作。它不是协议符合性验证，不构成规范安全漏洞定论，也没有复现失败研究中的流行程度或频率。</p><p>仍需在真实接入系统中回答：谁有权把完成报告升级为验收决定，谁把阻止决定落实到实际动作？后续测试应绑定当前产物，分别检查无权角色、旧版本与业务证据不足时的动作结果。跨主体核验还需保护各方私有状态，本文没有验证这种能力。</p>',27))])}const _=i(s,[["render",h]]);export{f as __pageData,_ as default};
